prompt --application/set_environment
set define off verify off feedback off
whenever sqlerror exit sql.sqlcode rollback
--------------------------------------------------------------------------------
--
-- ORACLE Application Express (APEX) export file
--
-- You should run the script connected to SQL*Plus as the Oracle user
-- APEX_190200 or as the owner (parsing schema) of the application.
--
-- NOTE: Calls to apex_application_install override the defaults below.
--
--------------------------------------------------------------------------------
begin
wwv_flow_api.import_begin (
 p_version_yyyy_mm_dd=>'2019.10.04'
,p_release=>'19.2.0.00.18'
,p_default_workspace_id=>1
,p_default_application_id=>100
,p_default_id_offset=>0
,p_default_owner=>'HADER'
);
end;
/

prompt APPLICATION 100 - Hader
--
-- Application Export:
--   Application:     100
--   Name:            Hader
--   Exported By:     HADER
--   Flashback:       0
--   Export Type:     Component Export
--   Manifest
--     PLUGIN: COM.HADER.EMPLOYEE_TERMINALS
--   Manifest End
--   Version:         19.2.0.00.18
--   Instance ID:     1
--

prompt --application/shared_components/plugins/region_type/com_hader_employee_terminals
begin
wwv_flow_api.create_plugin(
 p_id=>wwv_flow_api.id(91734600000001)
,p_plugin_type=>'REGION TYPE'
,p_name=>'COM.HADER.EMPLOYEE_TERMINALS'
,p_display_name=>'Hader Employee on the Terminals (حاضر - الموظف على الأجهزة)'
,p_supported_ui_types=>'DESKTOP:JQM_SMARTPHONE'
,p_javascript_file_urls=>'#PLUGIN_FILES#hader-employee.js'
,p_css_file_urls=>'#PLUGIN_FILES#hader-employee.css'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Hader employee on the terminals (region plug-in). APEX 19.2 and later, Oracle 11g and later.',
'-- Hader for Oracle APEX (native): one employee''s areas (which terminals hold them), templates and photos',
'-- kept in the database, where they stand on each terminal, and remote enrollment of a finger, face or palm.',
'-- The employee is read from the page item in session state (protect it with Session State Protection).',
'',
'function obj (p_region in apex_plugin.t_region, p_name in varchar2) return varchar2 is',
'  l_owner varchar2(200) := trim(p_region.attribute_01);',
'begin',
'  if l_owner is null then',
'    return p_name;',
'  end if;',
'  if not regexp_like(l_owner, ''^[A-Za-z][A-Za-z0-9_$#]{0,29}$'') then',
'    raise_application_error(-20001, ''Hader: invalid owner '' || l_owner);',
'  end if;',
'  return l_owner || ''.'' || p_name;',
'end obj;',
'',
'-- may this user change things (attribute "Allow changes" and the optional authorization scheme)?',
'function can_change (p_region in apex_plugin.t_region) return boolean is',
'begin',
'  return nvl(p_region.attribute_03, ''Y'') = ''Y''',
'     and (p_region.attribute_04 is null or apex_authorization.is_authorized(p_region.attribute_04));',
'end can_change;',
'',
'procedure print_clob (p_clob in clob) is',
'  l_len number := dbms_lob.getlength(p_clob);',
'begin',
'  for i in 0 .. trunc((nvl(l_len, 0) - 1) / 8000) loop',
'    sys.htp.prn(dbms_lob.substr(p_clob, 8000, i * 8000 + 1));',
'  end loop;',
'end print_clob;',
'',
'-- "ORA-20601: message" -> "message" (the messages of Hader are written for the page)',
'function message (p_err in varchar2) return varchar2 is',
'  l_first varchar2(4000) := regexp_substr(p_err, ''^[^'' || chr(10) || '']*'');',
'begin',
'  return case when regexp_like(l_first, ''^ORA-206[0-9][0-9]: '') then regexp_replace(l_first, ''^ORA-[0-9]+: '') else l_first end;',
'end message;',
'',
'function render (',
'  p_region              in apex_plugin.t_region,',
'  p_plugin              in apex_plugin.t_plugin,',
'  p_is_printer_friendly in boolean )',
'  return apex_plugin.t_region_render_result',
'is',
'  l_id varchar2(255) := nvl(p_region.static_id, ''R'' || p_region.id) || ''_hdr'';',
'begin',
'  sys.htp.p(''<div id="'' || apex_escape.html_attribute(l_id) || ''" class="hdr-e"><div class="hdr-e-load"></div></div>'');',
'  apex_javascript.add_onload_code(',
'    ''hdrEmpTerminals.init('' ||',
'    apex_javascript.add_value(l_id) ||',
'    apex_javascript.add_value(apex_plugin.get_ajax_identifier) ||',
'    apex_javascript.add_value(p_region.attribute_02) ||                          -- employee item',
'    apex_javascript.add_value(case when can_change(p_region) then ''Y'' else ''N'' end) ||',
'    apex_javascript.add_value(nvl(p_region.attribute_05, ''AUTO'')) ||              -- language',
'    apex_javascript.add_value(p_region.attribute_06, false) ||                     -- parts shown',
'    '');'');',
'  return null;',
'end render;',
'',
'function ajax (',
'  p_region in apex_plugin.t_region,',
'  p_plugin in apex_plugin.t_plugin )',
'  return apex_plugin.t_region_ajax_result',
'is',
'  l_what varchar2(20) := apex_application.g_x01;',
'  l_emp  varchar2(30) := substr(trim(v(p_region.attribute_02)), 1, 30);   -- session state, not the browser',
'  l_clob clob;',
'  l_blob blob;',
'  l_n    number;',
'begin',
'  if l_what = ''PHOTO'' then',
'    execute immediate ''begin :r := '' || obj(p_region, ''HDR_UI'') || ''.photo(:e); end;'' using out l_blob, l_emp;',
'    if l_blob is null or dbms_lob.getlength(l_blob) = 0 then',
'      sys.owa_util.status_line(404, ''Not Found'', true);',
'    else',
'      sys.owa_util.mime_header(''image/jpeg'', false);',
'      sys.htp.p(''Content-Length: '' || dbms_lob.getlength(l_blob));',
'      sys.htp.p(''Cache-Control: private, max-age=300'');',
'      sys.owa_util.http_header_close;',
'      sys.wpg_docload.download_file(l_blob);',
'    end if;',
'    return null;',
'  end if;',
'  if l_emp is null then',
'    apex_json.open_object;',
'    apex_json.write(''empty'', true);',
'    apex_json.close_object;',
'  elsif l_what = ''GET'' then',
'    execute immediate ''begin :r := '' || obj(p_region, ''HDR_UI'') || ''.employee(:e); end;'' using out l_clob, l_emp;',
'    print_clob(l_clob);',
'  elsif l_what = ''DO'' then',
'    if not can_change(p_region) then',
'      raise_application_error(-20699, ''غير مسموح — not allowed'');',
'    end if;',
'    execute immediate ''begin :r := '' || obj(p_region, ''HDR_UI'') || ''.employee_do(:e, :a, :p1, :p2, :p3); end;''',
'      using out l_n, l_emp, apex_application.g_x02, apex_application.g_x03, apex_application.g_x04, apex_application.g_x05;',
'    apex_json.open_object;',
'    apex_json.write(''ok'', true);',
'    apex_json.write(''count'', l_n);',
'    apex_json.close_object;',
'  end if;',
'  return null;',
'exception when others then',
'  apex_json.free_output;',
'  sys.htp.init;',
'  apex_json.open_object;',
'  apex_json.write(''failure'', message(sqlerrm) ||   -- not ''error'': apex.server takes that one for its own',
'    case when sqlcode in (-6550, -942) then '' — install Hader for Oracle APEX and run HDR_UI.grant_to for this schema'' end);',
'  apex_json.close_object;',
'  return null;',
'end ajax;'))
,p_api_version=>1
,p_render_function=>'render'
,p_ajax_function=>'ajax'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Hader for Oracle APEX (native): one employee — the areas whose terminals hold them, the fingerprints, faces and palms kept in the database, where they stand on each terminal, and enrolling a finger, face or palm on a terminal from the page; read from, send to or remove from the terminals.'
,p_version_identifier=>'1.3'
,p_files_version=>59425
);
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(91734600000002)
,p_plugin_id=>wwv_flow_api.id(91734600000001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Owner of Hader for Oracle APEX'
,p_attribute_type=>'TEXT'
