,p_display_length=>30
,p_max_length=>30
,p_is_translatable=>false
,p_help_text=>'Schema of Hader for Oracle APEX (the one with HDR_UI). Empty = the application''s parsing schema. Run SELECT HDR_UI.grant_to(''<parsing schema>'') FROM DUAL as that schema once.'
);
