,p_help_text=>'Page item holding the employee number (EMP_CODE). The region reloads when it changes. It is read from session state on the server: protect it (Session State Protection) if users must not open each other.'
);
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(91734600000004)
,p_plugin_id=>wwv_flow_api.id(91734600000001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'Allow changes'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'Y'
,p_is_translatable=>false
,p_help_text=>'Users who see the region may change things (server address, clock, people, settings). Off = look only. The database checks this on every request, not only the page.'
);
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(91734600000005)
,p_plugin_id=>wwv_flow_api.id(91734600000001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_prompt=>'Authorization scheme for changes'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_display_length=>30
,p_max_length=>255
,p_is_translatable=>false
,p_help_text=>'Optional: name of an authorization scheme of the application (e.g. Administration Rights). Only users it accepts may change things; the others see the region read only. Checked on the server for every request.'
);
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(91734600000006)
,p_plugin_id=>wwv_flow_api.id(91734600000001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>5
